import { FC, HTMLAttributes, useEffect, useState } from 'react';
import { Trans, useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router-dom';

import { Button, Flex, Switch, Typography } from 'antd';

import robotImage from 'assets/images/emptyStates/robot.webp';
import AttentionIcon from 'assets/images/icons/notes/attention.svg?react';
import UserIcon from 'assets/images/icons/notes/user.svg?react';
import { Instruction } from 'entities/Channel';
import { ADD_BOT_LINK, TELEREV_BOT_NAME } from 'shared/consts';
import { useBackButton, useCommonSlice } from 'shared/hooks';
import { EMainRoutes } from 'shared/typings';
import { BottomPanel, Content, Note, Page } from 'shared/ui';
import { WebApp, WebView } from 'shared/utils';

import styles from './AddChannel.module.scss';

interface IAddChannelProps extends HTMLAttributes<HTMLDivElement> {}

export const AddChannel: FC<IAddChannelProps> = () => {
	const { t } = useTranslation();
	const navigate = useNavigate();

	const [isInstructionOpen, setIsInstructionOpen] = useState(false);
	const { isAllowWrite, setIsAllowWrite } = useCommonSlice();

	const listener = () => {
		navigate(`/${EMainRoutes.CHANNELS}/`);
	};

	useBackButton(`/${EMainRoutes.CHANNELS}`);

	useEffect(() => {
		WebApp?.onEvent('activated', listener);

		return () => {
			WebApp?.offEvent('activated', listener);
		};
	}, []); // eslint-disable-line react-hooks/exhaustive-deps

	return (
		<Page className={styles.page}>
			<Content className={styles.content} bordered={false}>
				<Flex vertical justify="center" align="center" gap={12}>
					<img src={robotImage} width={80} height={80} alt="robot" />

					<Typography.Title level={3} style={{ margin: 0 }}>
						{t('Добавление канала')}
					</Typography.Title>

					<Typography.Text type="secondary">
						<Trans i18nKey="add_channel_instruction">
							Для добавления нового канала, пожалуйста, добавьте бота{' '}
							<Typography.Link href={`https://t.me/${TELEREV_BOT_NAME}`} target="_blank">
								@{{ botName: TELEREV_BOT_NAME } as unknown as string}
							</Typography.Link>{' '}
							с правами администратора в этот канал.
						</Trans>
					</Typography.Text>

					<div className={styles.notes}>
						<Note icon={<UserIcon />}>{t('Для добавления канала в нем должно быть 1000+ подписчиков')}</Note>
						<Note icon={<AttentionIcon />} type="warning">
							{t('Не удаляйте бота из канала, иначе всё сломается')}
						</Note>
					</div>
				</Flex>
			</Content>

			<BottomPanel>
				<Flex vertical justify="stretch" align="center" gap={8} className={styles.bottomPanel}>
					{isAllowWrite && (
						<Typography.Text type="secondary">
							{t('Бот не будет удалять или размещать контент без вашего ведома')}
						</Typography.Text>
					)}

					{!isAllowWrite && (
						<Flex className={styles.allow} gap={12}>
							<Flex vertical gap={4}>
								<Typography.Text>{t('Разрешить получать сообщения от бота')}</Typography.Text>
								<Typography.Text type="secondary" className={styles.allowNote}>
									{t(
										'Никакой рекламы и спама, только системные уведомления. Бот не будет удалять или размещать контент без вашего ведома.',
									)}
								</Typography.Text>
							</Flex>
							<Switch
								value={isAllowWrite}
								onChange={() => WebApp?.requestWriteAccess((accessGranted) => setIsAllowWrite(accessGranted))}
							/>
						</Flex>
					)}

					{!WebView?.isIframe && (
						<Button href={ADD_BOT_LINK} type="primary" size="large" block>
							{t('Выбрать канал')}
						</Button>
					)}

					{WebView?.isIframe && (
						<Button type="primary" size="large" block onClick={() => setIsInstructionOpen(true)}>
							{t('Инструкция по добавлению')}
						</Button>
					)}
				</Flex>
			</BottomPanel>

			<Instruction open={isInstructionOpen} onCancel={() => setIsInstructionOpen(false)} />
		</Page>
	);
};

export default AddChannel;
