import { FC } from 'react';

import { Flex, type FlexProps, Typography } from 'antd';
import cn from 'classnames';

import styles from './Note.module.scss';

interface INoteProps extends FlexProps {
	icon?: React.ReactNode;
	type?: 'info' | 'warning' | 'error';
}

export const Note: FC<INoteProps> = ({ className, children, icon, type = 'info', ...props }) => {
	return (
		<Flex className={cn(className, styles.note, styles[type])} vertical align="center" gap={8} {...props}>
			{icon}
			<Typography.Text style={{ fontSize: 12 }}>{children}</Typography.Text>
		</Flex>
	);
};
